using Azure.Messaging.ServiceBus;using Azure.Storage.Blobs;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class Worker(ServiceBusClientFactory factory,BlobServiceClient blobs,ProcessingPipeline pipeline,IMessagePublisher publisher,ILogger<Worker> log,IConfiguration config):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create(Topics.IngestionEvents,"processing-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<DocumentIngestionCompleted>(a.Message.Body.ToString(),new(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid ingestion event");var client=new BlobClient(new Uri(m.ExtractedTextUri),new Azure.Identity.DefaultAzureCredential());await using var stream=await client.OpenReadAsync(cancellationToken:a.CancellationToken);using var reader=new StreamReader(stream);var text=await reader.ReadToEndAsync(a.CancellationToken);var output=pipeline.Process(m,text,config.GetValue<int?>("Processing:MaxTokens")??500,config.GetValue<int?>("Processing:OverlapTokens")??50);await publisher.PublishAsync(Topics.ProcessingEvents,output,m.CorrelationId,a.CancellationToken);await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"Processing failed");if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Processing Service Bus error");return Task.CompletedTask;}}